import {motionState,motionFrame,motionCSS,motionHTML} from './experiments-core.mjs';
export function motionTool({change}){const $=id=>document.getElementById('motion-'+id),reduce=matchMedia('(prefers-reduced-motion: reduce)');let state=motionState(),phase=.25,playing=false,active=false,frame=0,last=0,lastPaint=0;
 function paint(){ $('preview').innerHTML=motionFrame(state,phase);$('phase').value=Math.round(phase*100);$('phase-value').textContent=Math.round(phase*100)+'%'}
 function tick(now){frame=0;if(!active||!playing||reduce.matches||document.hidden)return;if(last)phase=(phase+(now-last)/1000*state.speed/8)%1;last=now;if(now-lastPaint>=1000/30){paint();lastPaint=now}frame=requestAnimationFrame(tick)}
 function sync(){cancelAnimationFrame(frame);frame=0;last=0;if(reduce.matches)playing=false;$('play').disabled=reduce.matches;$('play').textContent=reduce.matches?'Reduced motion enabled':playing?'Pause animation':'Play animation';$('play').setAttribute('aria-pressed',String(playing));if(active&&playing&&!document.hidden)frame=requestAnimationFrame(tick)}
 function draw(){for(const key of Object.keys(state))if($(key))$(key).value=state[key];for(const key of ['speed','amount','amplitude','x1','y1','x2','y2'])$(key+'-value').textContent=key==='speed'?state[key]+'×':String(state[key]);const easing=state.kind==='easing';$('background-controls').hidden=easing;$('easing-controls').hidden=!easing;$('css').hidden=!easing;$('duration').textContent=easing?`${(4/state.speed).toFixed(2)} seconds each way · cubic-bezier(${state.x1}, ${state.y1}, ${state.x2}, ${state.y2})`:`${(8/state.speed).toFixed(2)} seconds per loop · movement changes the artwork`;paint();sync();change()}
 for(const key of Object.keys(state))if($(key))$(key).oninput=e=>{state=motionState({...state,[key]:e.target.value});if(['x1','y1','x2','y2'].includes(key))$('preset').value='';draw()};
 $('preset').onchange=e=>{const presets={gentle:[.22,0,.36,1],standard:[.4,0,.2,1],linear:[0,0,1,1],snappy:[.76,0,.24,1]},v=presets[e.target.value];if(v){state=motionState({...state,x1:v[0],y1:v[1],x2:v[2],y2:v[3]});draw()}};
 $('play').onclick=()=>{playing=!playing;sync()};$('phase').oninput=e=>{playing=false;phase=Math.min(1,Math.max(0,Number(e.target.value)/100));paint();sync();change()};$('reset').onclick=()=>{state=motionState();phase=.25;playing=false;draw()};reduce.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);draw();
 return {get:()=>({...state,phase}),set:s=>{if(s){state=motionState(s);phase=Number.isFinite(s.phase)?Math.max(0,Math.min(1,s.phase)):.25;playing=false;draw()}},activate:v=>{active=v;sync()},svg:()=>motionFrame(state,phase),html:()=>motionHTML({...state,phase}),css:()=>motionCSS(state)}
}
